// SPDX-License-Identifier: GPL-3.0-or-later
//! The `/licenses` page: this program's license and the notices of everything it ships (ADR 0010),
//! the device and the desktop program (ADR 0020) alike. The crate notices are generated by
//! cargo-about (`just licenses`); the font license and the WebView2 SDK license (its loader is
//! linked into the Windows desktop program) are bundled.

use std::sync::LazyLock;

const SERVER_CRATES: &str = include_str!("../assets/licenses-server.html");
const WEB_CRATES: &str = include_str!("../assets/licenses-web.html");
const LATO_LICENSE: &str = include_str!("../../../assets/fonts/OFL-Lato.txt");
const WEBVIEW2_LICENSE: &str = include_str!("../assets/webview2-sdk-license.txt");

/// The complete page, built once.
pub static PAGE: LazyLock<String> = LazyLock::new(|| {
    format!(
        "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\
<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>sursum – licenses</title>\
<style>body{{font-family:system-ui,sans-serif;max-width:60rem;margin:auto;padding:1rem;background:#111;color:#eee}}\
pre{{white-space:pre-wrap;background:#1c1c1c;padding:1rem;font-size:0.8rem}}a{{color:#93c5fd}}</style></head><body>\
<p><a href=\"/remote/\">&larr; sursum</a></p><h1>sursum</h1><p>Copyright (C) 2026 Dominik Pieczyński and contributors.</p>\
<p>This program is free software: you can redistribute it and/or modify it under the terms of the GNU General \
Public License as published by the Free Software Foundation, either version 3 of the License, or (at your \
option) any later version. It is distributed WITHOUT ANY WARRANTY; see \
<a href=\"https://www.gnu.org/licenses/gpl-3.0.html\">the GNU General Public License</a>. Source code: \
<a href=\"https://github.com/dpieczynski/sursum\">github.com/dpieczynski/sursum</a>.</p>\
<h2>Server and desktop program: third-party Rust crates</h2>{SERVER_CRATES}\
<h2>Screen and remote: third-party Rust crates</h2>{WEB_CRATES}\
<h2>Fonts</h2><p>Lato by Łukasz Dziedzic, SIL Open Font License 1.1:</p><pre>{}</pre>\
<h2>Desktop program on Windows: WebView2 loader</h2><p>Microsoft WebView2 SDK, BSD 3-Clause \
License:</p><pre>{}</pre></body></html>",
        escape_html(LATO_LICENSE),
        escape_html(WEBVIEW2_LICENSE)
    )
});

fn escape_html(text: &str) -> String {
    text.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn page_contains_all_parts() {
        assert!(PAGE.contains("GNU General Public License"));
        assert!(PAGE.contains("SIL OPEN FONT LICENSE"));
        assert!(PAGE.contains("tokio"), "server crate notices missing");
        assert!(PAGE.contains("leptos"), "web app crate notices missing");
        assert!(PAGE.contains("Microsoft Corporation"), "WebView2 SDK license missing");
        assert!(PAGE.contains("href=\"/remote/\""), "no way back to the remote");
    }
}
